35	// ─── Social link button ───────────────────────────────────────────────────────
36	
37	function SocialLink({
38	  href,
39	  label,
40	  children,
41	}: {
42	  href: string;
43	  label: string;
44	  children: React.ReactNode;
45	}) {
46	  return (
47	    <a
48	      href={href}
49	      target="_blank"
50	      rel="noopener noreferrer"
51	      aria-label={label}
52	      className={styles['footer-social-link']}
53	    >
54	      {children}
55	    </a>
56	  );
57	}
