169	// ─── Footer link columns ──────────────────────────────────────────────────────
170	
171	type FooterLink = {
172	  label: string;
173	  href: string;
174	  external?: boolean;
175	  comingSoon?: boolean;
176	};
177	
178	const footerLinks: Record<string, FooterLink[]> = {
179	  About: [
180	    { label: "Our Mission", href: "/our-mission" },
181	    { label: "How It Works", href: "/how-it-works" },
182	    { label: "Portfolio", href: "/our-works" },
183	    { label: "Pricing", href: "/pricing" },
184	  ],
185	  Services: [
186	    { label: "Web Development", href: "/services/website-development" },
187	    { label: "UI UX Design", href: "#", comingSoon: true },
188	    { label: "Graphics Design", href: "#", comingSoon: true },
189	  ],
190	  Resources: [
191	    { label: "Blog", href: "/blog" },
192	    { label: "Affiliate", href: "#", comingSoon: true },
193	    { label: "Careers", href: "/careers" },
194	  ],
195	  Help: [
196	    { label: "Contact us", href: "/contact" },
197	    { label: "Help center", href: "https://help.boldteq.com", external: true },
198	    { label: "Terms of Service", href: "/terms-of-service" },
199	    { label: "Privacy Policy", href: "/privacy-policy" },
200	  ],
201	};
202	
203	function FooterLinkColumn({ title, links }: { title: string; links: FooterLink[] }) {
204	  return (
205	    <div className={styles['column-x-large-inner']}>
206	      <div className={styles['footer-title']}>{title}</div>
207	      <div className={styles['column-regular-2']}>
208	        {links.map((link) => {
209	          const inner = (
210	            <span className={styles['coming-soon-out']}>
211	              {link.label}
212	              {link.comingSoon && (
213	                <span className={styles['coming-soon-badge']}>Coming Soon</span>
214	              )}
215	            </span>
216	          );
217	
218	          if (link.comingSoon) {
219	            return (
220	              <span
221	                key={link.label}
222	                className={`${styles['footer-link']} ${styles['disabled']}`}
223	              >
224	                {inner}
225	              </span>
226	            );
227	          }
228	
229	          if (link.external) {
230	            return (
231	              <a
232	                key={link.label}
233	                href={link.href}
234	                target="_blank"
235	                rel="noopener noreferrer"
236	                className={styles['footer-link']}
237	              >
238	                {inner}
239	              </a>
240	            );
241	          }
242	
243	          return (
244	            <Link
245	              key={link.label}
246	              href={link.href}
247	              className={styles['footer-link']}
248	            >
249	              {inner}
250	            </Link>
251	          );
252	        })}
253	      </div>
254	    </div>
255	  );
256	}
257	
