1	/* ─── Navbar CSS Module ───────────────────────────────────────────────────────
2	   Extracted verbatim from boldteq-v1-0.webflow.css
3	   All class names preserved exactly; use bracket notation in JSX for hyphenated names
4	   ─────────────────────────────────────────────────────────────────────────── */
5	
6	/* ─── Banner strip ──────────────────────────────────────────────────────────── */
7	
8	.banner-section {
9	  color: #fff;
10	  background-color: #082753;
11	  width: 100%;
12	  padding: 10px 5%;
13	  position: relative;
14	}
15	
16	.banner-content {
17	  grid-column-gap: 12px;
18	  grid-row-gap: 12px;
19	  color: #fff;
20	  justify-content: center;
21	  align-items: center;
22	  display: flex;
23	}
24	
25	.paragraph-regular {
26	  color: #fff;
27	  margin-bottom: 0;
28	  font-family: Roobert PRO, Arial, sans-serif;
29	  font-size: 14px;
30	  line-height: 24px;
31	}
32	
33	.paragraph-regular.capitalize {
34	  text-transform: capitalize;
35	}
36	
37	.beta-link {
38	  color: #21cfff;
39	  background-color: #0e2d54;
40	  border: 1px solid #21cfff40;
41	  border-radius: 6px;
42	  padding: 2px 10px;
43	  font-size: 13px;
44	  font-weight: 600;
45	  line-height: 24px;
46	  text-decoration: none;
47	  white-space: nowrap;
48	  transition: background-color 0.2s, color 0.2s;
49	}
50	
51	.beta-link:hover {
52	  background-color: #21cfff;
53	  color: #082753;
54	}
55	
56	/* ─── Outer header section ───────────────────────────────────────────────────── */
57	
58	.header-sec {
59	  text-align: center;
60	  background-color: #fff;
61	  flex-flow: column;
62	  justify-content: flex-start;
63	  align-items: center;
64	  display: flex;
65	}
66	
67	/* ─── Navbar wrapper ─────────────────────────────────────────────────────────── */
68	
69	.navbar {
70	  z-index: 999999;
71	  text-align: center;
72	  background-color: #fff;
73	  width: 100%;
74	  padding: 6px 1%;
75	  position: relative;
76	  transition: transform 0.5s ease, background-color 0.5s ease;
77	}
78	
79	/* Sticky navbar — matches Webflow custom code exactly */
80	.navbar.sticky {
81	  margin: 0 auto;
82	  position: fixed;
83	  top: 0;
84	  left: auto;
85	  right: auto;
86	  width: 96%;
87	  z-index: 999999;
88	  border: 1px solid rgba(255, 255, 255, 0.8);
89	  backdrop-filter: blur(6px);
90	  -webkit-backdrop-filter: blur(6px);
91	  background-color: rgba(255, 255, 255, 0.8);
92	  border-radius: 10px;
93	  box-shadow: rgba(0, 0, 0, 0.1) 0px 4px 16px -4px;
94	  opacity: 1;
95	  padding: 6px 1%;
96	  transform: translateY(10px);
97	}
98	
99	/* ─── Nav container (flex row — logo | menu | right) ─────────────────────────── */
100	
101	.nav-23-container {
102	  grid-column-gap: 10px;
103	  grid-row-gap: 10px;
104	  justify-content: space-between;
105	  width: 100%;
106	  max-width: none;
107	  margin-left: auto;
108	  margin-right: auto;
109	  display: flex;
110	}
111	
112	/* ─── Logo ───────────────────────────────────────────────────────────────────── */
113	
114	.nav-23-logo {
115	  width: 130px;
116	  height: 100%;
117	  padding-left: 0;
118	  padding-right: 0;
119	  display: inline-flex;
120	  text-decoration: none;
121	}
122	
123	.logo {
124	  object-fit: contain;
125	  width: 100%;
126	  height: 100%;
127	}
128	
129	/* ─── Left side ──────────────────────────────────────────────────────────────── */
130	
131	.nav-23-left {
132	  grid-column-gap: 40px;
133	  grid-row-gap: 40px;
134	  flex: 0 auto;
135	  justify-content: flex-start;
136	  align-items: center;
137	  display: flex;
138	}
139	
140	/* ─── Nav menu (desktop: flex row; mobile: column overlay) ───────────────────── */
141	
142	.nav-23-menu {
143	  align-items: center;
144	  display: flex;
145	  position: static;
146	}
147	
148	/* ─── Nav links row ──────────────────────────────────────────────────────────── */
149	
150	.nav-23-links {
151	  grid-column-gap: 2px;
152	  grid-row-gap: 2px;
153	  justify-content: flex-start;
154	  align-items: center;
155	  display: flex;
156	}
157	
158	/* ─── Regular nav link ───────────────────────────────────────────────────────── */
159	
160	.nav-23-link {
161	  color: #000;
162	  white-space: nowrap;
163	  background-color: transparent;
164	  border-radius: 8px;
165	  padding: 8px 5px;
166	  text-decoration: none;
167	  transition: background-color 0.3s, color 0.3s;
168	  display: inline-flex;
169	  align-items: center;
170	}
171	
172	.nav-23-link:hover {
173	  color: #000;
174	  background-color: transparent;
175	}
176	
177	.nav-23-link.w--current {
178	  color: #000;
179	}
180	
181	/* ─── Menu text ──────────────────────────────────────────────────────────────── */
182	
183	.menu-text {
184	  color: #082753;
185	  font-family: Roobert PRO, Arial, sans-serif;
186	  font-size: 16px;
187	  font-weight: 500;
188	  line-height: 1.5;
189	}
190	
191	/* ─── Dropdown wrapper ───────────────────────────────────────────────────────── */
192	
193	.nav-23-dropdown {
194	  margin-left: 0;
195	  margin-right: 0;
196	  position: relative;
197	}
198	
199	/* ─── Dropdown toggle ────────────────────────────────────────────────────────── */
200	
201	.nav-23-dropdown-toggle {
202	  grid-column-gap: 4px;
203	  grid-row-gap: 4px;
204	  color: #000;
205	  white-space: nowrap;
206	  background-color: transparent;
207	  border-radius: 8px;
208	  justify-content: flex-start;
209	  align-items: center;
210	  padding: 8px 8px 8px 10px;
211	  font-size: 16px;
212	  line-height: 1.5;
