328	function NavDropdown({ item }: { item: NavItem }) {
329	  const [open, setOpen] = useState(false);
330	  const containerRef = useRef<HTMLDivElement>(null);
331	  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
332	
333	  const handleMouseEnter = useCallback(() => {
334	    if (timerRef.current) clearTimeout(timerRef.current);
335	    setOpen(true);
336	  }, []);
337	
338	  const handleMouseLeave = useCallback(() => {
339	    timerRef.current = setTimeout(() => setOpen(false), 120);
340	  }, []);
341	
342	  useEffect(() => {
343	    return () => {
344	      if (timerRef.current) clearTimeout(timerRef.current);
345	    };
346	  }, []);
347	
348	  const isSolutions = item.label === "Solutions";
349	  const isLast = item.label === "Resources";
350	
351	  return (
352	    // .nav-23-dropdown
353	    <div
354	      ref={containerRef}
355	      className={styles["nav-23-dropdown"]}
356	      onMouseEnter={handleMouseEnter}
357	      onMouseLeave={handleMouseLeave}
358	    >
359	      {/* .nav-23-dropdown-toggle (+ .last-child for Resources) */}
360	      <button
