411	// ─── Sticky scroll hook ───────────────────────────────────────────────────────
412	
413	function useStickyNav() {
414	  const [sticky, setSticky] = useState(false);
415	
416	  useEffect(() => {
417	    const getOffset = () =>
418	      window.matchMedia("(max-width: 767px)").matches ? 350 : 300;
419	    let offset = getOffset();
420	
421	    const handleScroll = () => {
422	      setSticky(window.scrollY > offset);
423	    };
424	
425	    const handleResize = () => {
426	      offset = getOffset();
427	    };
428	
429	    window.addEventListener("scroll", handleScroll, { passive: true });
430	    window.addEventListener("resize", handleResize, { passive: true });
431	    return () => {
432	      window.removeEventListener("scroll", handleScroll);
433	      window.removeEventListener("resize", handleResize);
434	    };
435	  }, []);
436	
437	  return sticky;
438	}
